26	/// Run a request.
27	///
28	/// This is the "main loop" of entire ureq.
29	pub(crate) fn run(
30	    agent: &Agent,
31	    mut request: Request<()>,
32	    mut body: SendBody,
33	) -> Result<Response<Body>, Error> {
34	    let mut redirect_count = 0;
35	
36	    // Configuration on the request level overrides the agent level.
37	    let (config, request_level) = request
38	        .extensions_mut()
39	        .remove::<RequestLevelConfig>()
40	        .map(|rl| (Arc::new(rl.0), true))
41	        .unwrap_or_else(|| (agent.config.clone(), false));
42	
43	    let force_send_body = request.extensions_mut().remove::<ForceSendBody>().is_some();
44	
45	    let mut redirect_history: Option<Vec<Uri>> =
46	        config.save_redirect_history().then_some(Vec::new());
47	
48	    let timeouts = config.timeouts();
49	
50	    let mut timings = CallTimings::new(timeouts, CurrentTime::default()).with_io_timeouts(&config);
51	
52	    let mut call = Call::new(request)?;
53	
54	    if force_send_body {
55	        call.force_send_body();
56	    }
57	
58	    call.allow_non_standard_methods(config.allow_non_standard_methods());
59	
60	    let (response, handler) = loop {
61	        let timeout = timings.next_timeout(Timeout::Global);
62	        let timed_out = match timeout.after {
63	            Duration::Exact(v) => v.is_zero(),
64	            Duration::NotHappening => false,
65	        };
66	        if timed_out {
67	            return Err(Error::Timeout(Timeout::Global));
68	        }
69	
70	        match call_run(
71	            agent,
72	            &config,
73	            request_level,
74	            call,
75	            &mut body,
76	            redirect_count,
77	            &mut redirect_history,
78	            &mut timings,
79	        )? {
80	            // Follow redirect
81	            CallResult::Redirect(rcall, rtimings) => {
82	                redirect_count += 1;
83	
84	                call = handle_redirect(rcall, &config)?;
85	
86	                // If the new method doesn't need a body, clear it.
87	                // This prevents Content-Length/Transfer-Encoding headers from being added
88	                // on methods like GET that don't send bodies (e.g., POST->GET redirects).
89	                let method = call.method();
90	                if !matches!(method, &Method::POST | &Method::PUT | &Method::PATCH) {
91	                    body.remove();
92	                }
93	
94	                timings = rtimings.new_call();
95	            }
96	
97	            // Return response
98	            CallResult::Response(response, handler) => break (response, handler),
99	        }
100	    };
101	
102	    let (mut parts, _) = response.into_parts();
103	
104	    let recv_body_mode = handler
105	        .call
106	        .as_ref()
107	        .map(|f| f.body_mode())
108	        .unwrap_or(BodyMode::NoBody);
109	
110	    let info = ResponseInfo::new(&parts.headers, recv_body_mode);
111	
112	    // If the body will be decompressed, strip Content-Encoding and Content-Length
113	    // from the response headers. The Content-Length no longer matches the
114	    // decompressed body size, and Content-Encoding no longer applies since
115	    // the body is delivered to the caller already decompressed (RFC 9110 §8.7).
116	    if info.is_decompressing() {
117	        parts.headers.remove(http::header::CONTENT_ENCODING);
118	        parts.headers.remove(http::header::CONTENT_LENGTH);
119	    }
120	
121	    let body = Body::new(handler, info);
122	
123	    let response = Response::from_parts(parts, body);
124	
125	    let status = response.status();
126	    let is_err = status.is_client_error() || status.is_server_error();
127	
128	    if config.http_status_as_error() && is_err {
129	        return Err(Error::StatusCode(status.as_u16()));
130	    }
131	
132	    Ok(response)
133	}
