258	/// Return type of [`call_run`].
259	#[allow(clippy::large_enum_variant)]
260	enum CallResult {
261	    /// Call resulted in a redirect.
262	    Redirect(Call<Redirect>, CallTimings),
263	
264	    /// Call resulted in a response.
265	    Response(Response<()>, BodyHandler),
266	}
