361	fn connect(
362	    agent: &Agent,
363	    config: &Config,
364	    request_level: bool,
365	    uri: &Uri,
366	    timings: &mut CallTimings,
367	) -> Result<Connection, Error> {
368	    // Before resolving the URI we need to ensure it is a full URI. We
369	    // cannot make requests with partial uri like "/path".
370	    uri.ensure_valid_url()?;
371	
372	    let is_proxy = config.proxy().is_some();
373	
374	    // For most proxy configs, the proxy itself should resolve the host name we are connecting to.
375	    // However for SOCKS4, we must do it and pass the resolved IP to the proxy.
376	    let is_proxy_local_resolve = config.proxy().map(|p| p.resolve_target()).unwrap_or(false);
377	
378	    // Tells if this host matches NO_PROXY
379	    let is_no_proxy = config.proxy().map(|p| p.is_no_proxy(uri)).unwrap_or(false);
380	
381	    let addrs = if is_no_proxy || !is_proxy || is_proxy_local_resolve {
382	        agent
383	            .resolver
384	            .resolve(uri, config, timings.next_timeout(Timeout::Resolve))?
385	    } else {
386	        agent.resolver.empty()
387	    };
388	
389	    timings.record_time(Timeout::Resolve);
390	
391	    let details = ConnectionDetails {
392	        uri,
393	        addrs,
394	        resolver: &*agent.resolver,
395	        config,
396	        request_level,
397	        now: timings.now(),
398	        timeout: timings.next_timeout(Timeout::Connect),
399	        current_time: timings.current_time(),
400	        run_connector: agent.run_connector.clone(),
401	    };
402	
403	    let use_pool = config.can_share_pool_with(&agent.config);
404	    let max_idle_age = config.max_idle_age().into();
405	    let connection = agent.pool.connect(&details, max_idle_age, use_pool)?;
406	
407	    if details.needs_tls() && !connection.is_tls() {
408	        return Err(Error::TlsRequired);
409	    }
410	
411	    timings.record_time(Timeout::Connect);
412	
413	    Ok(connection)
414	}
