441	fn await_100(
442	    mut call: Call<Await100>,
443	    connection: &mut Connection,
444	    timings: &mut CallTimings,
445	) -> Result<Await100Result, Error> {
446	    while call.can_keep_await_100() {
447	        let timeout = timings.next_timeout(Timeout::Await100);
448	
449	        if timeout.after.is_zero() {
450	            if timeout.reason == Timeout::Await100 {
451	                // Stop waiting for 100-continue.
452	                break;
453	            }
454	            return Err(Error::Timeout(timeout.reason));
455	        }
456	
457	        match connection.maybe_await_input(timeout) {
458	            Ok(_) => {
459	                let input = connection.buffers().input();
460	                if input.is_empty() {
461	                    return Err(Error::disconnected("await_100 empty input"));
462	                }
463	
464	                let amount = call.try_read_100(input)?;
465	                if amount > 0 {
466	                    connection.consume_input(amount);
467	                    break;
468	                }
469	            }
470	            Err(Error::Timeout(Timeout::Await100)) => {
471	                // If we get a timeout while waiting for input, that is not an error,
472	                // we progress to send the request body.
473	                break;
474	            }
475	            Err(e) => return Err(e),
476	        }
477	    }
478	
479	    timings.record_time(Timeout::Await100);
480	
481	    // A misconfigured request might surface here.
482	    let call = call.proceed()?;
483	
484	    Ok(call)
485	}
