487	fn send_body(
488	    mut call: Call<SendBodyState>,
489	    body: &mut SendBody,
490	    connection: &mut Connection,
491	    timings: &mut CallTimings,
492	) -> Result<Call<RecvResponse>, Error> {
493	    loop {
494	        if call.can_proceed() {
495	            break;
496	        }
497	
498	        let buffers = connection.buffers();
499	
500	        let (tmp, output) = buffers.tmp_and_output();
501	
502	        let input_len = tmp.len();
503	
504	        let input_fitting_in_output = call.calculate_max_input(output.len());
505	        let max_input = input_len.min(input_fitting_in_output);
506	
507	        let output_used = if !call.is_chunked() {
508	            // For non-chunked, The body can be written directly to the output.
509	            // This optimizes away a memcopy if we were to go via call.write().
510	            let output_used = body.read(output)?;
511	
512	            // Size checking is still in the call.
513	            call.consume_direct_write(output_used)?;
514	
515	            output_used
516	        } else {
517	            let tmp = &mut tmp[..max_input];
518	            let n = body.read(tmp)?;
519	
520	            let (input_used, output_used) = call.write(&tmp[..n], output)?;
521	
522	            // Since output is "a bit" larger than the input (compensate for chunk ovexrhead),
523	            // the entire input we read from the body should also be shipped to the output.
524	            assert!(input_used == n);
525	
526	            output_used
527	        };
528	
529	        let timeout = timings.next_timeout(Timeout::SendBody);
530	        connection.transmit_output(output_used, timeout)?;
531	    }
532	
533	    timings.record_time(Timeout::SendBody);
534	    Ok(call.proceed().unwrap())
535	}
