537	fn recv_response(
538	    mut call: Call<RecvResponse>,
539	    connection: &mut Connection,
540	    config: &Config,
541	    timings: &mut CallTimings,
542	    is_following_redirects: bool,
543	) -> Result<(Response<()>, RecvResponseResult), Error> {
544	    let response = loop {
545	        let timeout = timings.next_timeout(Timeout::RecvResponse);
546	        let made_progress = connection.maybe_await_input(timeout)?;
547	
548	        let input = connection.buffers().input();
549	
550	        // If cookies are disabled, we can allow ourselves to follow
551	        // the redirect as soon as we discover the `Location` header.
552	        // There are plenty of broken servers out there that don't send
553	        // the finishing \r\n on redirects. With cookies off, we can
554	        // handle that situation.
555	        //
556	        // If cookies are enabled, we risk mising a `Set-Cookie` header
557	        // with such a strategy.
558	        let cookies_enabled = cfg!(feature = "cookies");
559	
560	        // If we are not following redirects, do not allow partial returned
561	        // 302 responses.
562	        let allow_partial_redirect = !cookies_enabled && is_following_redirects;
563	
564	        let (amount, maybe_response) = call.try_response(input, allow_partial_redirect)?;
565	
566	        let check_size = if maybe_response.is_some() {
567	            // We got a parsed response, ensure the size is within
568	            // configured parameters.
569	            amount
570	        } else {
571	            // We did not parse a response, if input is too large,
572	            // we stop trying to get more data.
573	            input.len()
574	        };
575	
576	        if check_size > config.max_response_header_size() {
577	            return Err(Error::LargeResponseHeader(
578	                input.len(),
579	                config.max_response_header_size(),
580	            ));
581	        }
582	
583	        connection.consume_input(amount);
584	
585	        if let Some(response) = maybe_response {
586	            assert!(call.can_proceed());
587	            break response;
588	        } else if !made_progress {
589	            return Err(Error::disconnected("recv_respone made no progress"));
590	        }
591	    };
592	
593	    timings.record_time(Timeout::RecvResponse);
594	    Ok((response, call.proceed().unwrap()))
595	}
