597	fn handle_redirect(mut call: Call<Redirect>, config: &Config) -> Result<Call<Prepare>, Error> {
598	    let maybe_new_call = call.as_new_call(config.redirect_auth_headers())?;
599	    let status = call.status();
600	
601	    if let Some(call) = maybe_new_call {
602	        debug!(
603	            "Redirect ({}): {} {:?}",
604	            status,
605	            call.method(),
606	            DebugUri(call.uri())
607	        );
608	
609	        Ok(call)
610	    } else {
611	        Err(Error::RedirectFailed)
612	    }
613	}
