623	#[derive(Default)]
624	pub(crate) struct BodyHandler {
625	    call: Option<Call<RecvBody>>,
626	    connection: Option<Connection>,
627	    timings: CallTimings,
628	    remote_closed: bool,
629	    redirect: Option<Box<Call<Redirect>>>,
630	}
631	
632	impl BodyHandler {
633	    fn do_read(&mut self, buf: &mut [u8]) -> Result<usize, Error> {
634	        let (Some(call), Some(connection), timings) =
635	            (&mut self.call, &mut self.connection, &mut self.timings)
636	        else {
637	            return Ok(0);
638	        };
639	
640	        loop {
641	            let body_fulfilled = match call.body_mode() {
642	                BodyMode::NoBody => unreachable!("must be a BodyMode for BodyHandler"),
643	                // These modes are fulfilled by either reaching the content-length or
644	                // receiving an end chunk delimiter.
645	                BodyMode::LengthDelimited(_) | BodyMode::Chunked => call.can_proceed(),
646	                // This mode can only end once remote closes
647	                BodyMode::CloseDelimited => false,
648	            };
649	
650	            if body_fulfilled {
651	                self.ended()?;
652	                return Ok(0);
653	            }
654	
655	            let has_buffered_input = connection.buffers().can_use_input();
656	
657	            // First try to use input already buffered
658	            if has_buffered_input {
659	                let input = connection.buffers().input();
660	                let (input_used, output_used) = call.read(input, buf)?;
661	                connection.consume_input(input_used);
662	
663	                if output_used > 0 {
664	                    return Ok(output_used);
665	                }
666	
667	                if input_used > 0 {
668	                    // Body might be fulfilled now.
669	                    continue;
670	                }
671	            }
672	
673	            if self.remote_closed {
674	                // we should not try to await_input again.
675	                self.ended()?;
676	                return Ok(0);
677	            }
678	
679	            let timeout = timings.next_timeout(Timeout::RecvBody);
680	
681	            let made_progress = match connection.maybe_await_input(timeout) {
682	                Ok(v) => v,
683	                Err(Error::Io(e)) => match e.kind() {
684	                    io::ErrorKind::UnexpectedEof
685	                    | io::ErrorKind::ConnectionAborted
686	                    | io::ErrorKind::ConnectionReset => {
687	                        self.remote_closed = true;
688	                        true
689	                    }
690	                    _ => return Err(Error::Io(e)),
691	                },
692	                Err(e) => return Err(e),
693	            };
694	
695	            let input = connection.buffers().input();
696	            let input_ended = input.is_empty();
697	
698	            let (input_used, output_used) = call.read(input, buf)?;
699	            connection.consume_input(input_used);
700	
701	            if output_used > 0 {
702	                return Ok(output_used);
703	            } else if input_ended {
704	                self.ended()?;
705	                return Ok(0);
706	            } else if made_progress {
707	                // The maybe_await_input() made progress, but handled amount is 0. This
708	                // can for instance happen if we read some data, but not enough for
709	                // decoding any gzip.
710	                continue;
711	            } else {
712	                // This is an error case we don't want to see.
713	                return Err(Error::BodyStalled);
714	            }
715	        }
716	    }
717	
718	    fn ended(&mut self) -> Result<(), Error> {
719	        self.timings.record_time(Timeout::RecvBody);
720	
721	        let call = self.call.take().expect("ended() called with body");
722	
723	        // In some cases, when reading chunked, the server send 0\r\n to indicate
724	        // the end of the body, and then abruptly does a FIN. In these cases we have
725	        // received the entire body, but must clean up the connection.
726	        let is_ended_chunked = call.is_ended_chunked();
727	
728	        let mut force_close = false;
729	
730	        if !call.can_proceed() {
731	            if is_ended_chunked {
732	                // This case means we got 0\r\n, but can_proceed() is false because
733	                // it only goes true on fully received chunked bodies.
734	                debug!("Server ended connection after sending chunked 0\\r\\n");
735	                force_close = true;
736	            } else {
737	                return Err(Error::disconnected("ended call cannot proceed"));
738	            }
739	        }
740	
741	        let must_close_connection = force_close
742	            || match call.proceed().unwrap() {
743	                RecvBodyResult::Redirect(call) => {
744	                    let c = call.must_close_connection();
745	                    self.redirect = Some(Box::new(call));
746	                    c
747	                }
748	                RecvBodyResult::Cleanup(v) => v.must_close_connection(),
749	            };
750	
751	        let connection = self.connection.take().expect("ended() called with body");
752	        cleanup(connection, must_close_connection, self.timings.now());
753	
754	        Ok(())
755	    }
756	
757	    fn consume_redirect_body(&mut self) -> Result<Call<Redirect>, Error> {
758	        let mut buf = vec![0; 1024];
759	        loop {
760	            let amount = self.do_read(&mut buf)?;
761	            if amount == 0 {
762	                break;
763	            }
764	        }
765	
766	        // Unwrap is OK, because we are only consuming the redirect body if
767	        // such a body was signalled by the remote.
768	        let redirect = self.redirect.take().map(|b| *b);
769	        Ok(redirect.expect("remote to have signaled redirect"))
770	    }
771	}
772	
773	impl io::Read for BodyHandler {
774	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
775	        self.do_read(buf).map_err(|e| e.into_io())
776	    }
777	}
