    }
}

impl Private for Vec<u8> {}
impl AsSendBody for Vec<u8> {
    fn as_body(&mut self) -> SendBody {
        let inner = BodyInner::ByteSlice((*self).as_ref());
        (Some(self.len() as u64), inner).into()
    }
}

impl Private for &String {}
impl AsSendBody for &String {
    fn as_body(&mut self) -> SendBody {
        let inner = BodyInner::ByteSlice((*self).as_ref());
