impl Private for &File {}
impl AsSendBody for &File {
    fn as_body(&mut self) -> SendBody {
        let size = lazy_file_size(self);
        SendBody {
            inner: BodyInner::Reader(self),
            size: Some(size),
            ended: false,
            content_type: None,
        }
    }
}

impl Private for File {}
impl AsSendBody for File {
    fn as_body(&mut self) -> SendBody {
        let size = lazy_file_size(self);
        SendBody {
            inner: BodyInner::Reader(self),
            size: Some(size),
            ended: false,
            content_type: None,
        }
    }
}

fn lazy_file_size(file: &File) -> Result<u64, Error> {
    match file.metadata() {
        Ok(v) => Ok(v.len()),
        Err(e) => Err(e.into()),
    }
}

