752	impl io::Read for RxRead {
753	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
754	        let v = match self.0.recv() {
755	            Ok(v) => v,
756	            Err(_) => return Ok(0), // remote side is gone
