781	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
782	        if !self.1.is_empty() {
783	            let max = buf.len().min(self.1.len());
784	            buf[..max].copy_from_slice(&self.1[..max]);
785	            self.1.drain(..max);
786	            return Ok(max);
787	        }
788	
789	        let Some(reader) = &mut self.0 else {
790	            return Ok(0);
791	        };
792	        reader.read(buf)
793	    }
