796	impl<R: io::Read> SaneBufReader<R> {
797	    pub fn fill_buf(&mut self) -> io::Result<&[u8]> {
798	        let Some(reader) = &mut self.0 else {
799	            return Ok(&self.1);
800	        };
801	
802	        let l = self.1.len();
803	        self.1.resize(l + 1024, 0);
804	        let buf = &mut self.1[l..];
805	        let n = reader.read(buf)?;
806	        if n == 0 {
807	            self.0 = None;
808	        }
809	        self.1.truncate(l + n);
810	        Ok(&self.1)
811	    }
