847	        }
848	
849	        let input = self.buffers.input_append_buf();
850	        let mut buf = match self.rx.recv_timeout(timeout.after) {
851	            Ok(v) => v,
852	            Err(RecvTimeoutError::Timeout) => return Err(Error::Timeout(timeout.reason)),
853	            Err(RecvTimeoutError::Disconnected) => {
854	                trace!("Test server disconnected");
855	                self.connected_rx = false;
856	                return Err(Error::Io(io::Error::new(
857	                    io::ErrorKind::UnexpectedEof,
858	                    "test server disconnected",
859	                )));
860	            }
861	        };
862	
863	        let maybe_hangup = buf
864	            .windows(HANGUP.len())
865	            .enumerate()
866	            .find(|(_, w)| *w == HANGUP)
867	            .map(|(pos, _)| pos);
