/// Resolve a `Location` header against the URI of the request that received it.
///
/// Ported from ureq-proto's redirect handling, which does not expose this
/// for the body-replay path.
fn join_redirect_uri(base: Uri, location: &str) -> Option<Uri> {
    let mut parts = base.into_parts();

    let maybe = location.parse::<Uri>();
    let has_scheme = maybe.as_ref().ok().map(|u| u.scheme().is_some()).unwrap_or(false);

    if has_scheme {
        return maybe.ok();
    }

    if location.starts_with("//") {
        let scheme = parts.scheme.as_ref()?;
        let joined: Uri = format!("{}:{}", scheme.as_str(), location).parse().ok()?;
        return Some(joined);
    }

    if location.starts_with("/") {
        let pq: PathAndQuery = location.parse().ok()?;
        parts.path_and_query = Some(pq);
    } else {
        let base_path = parts.path_and_query.as_ref().map(|p| p.path()).unwrap_or("/");
        let total_path = join_relative_path(base_path, location)?;
        let pq: PathAndQuery = total_path.parse().ok()?;
        parts.path_and_query = Some(pq);
    }

    Uri::from_parts(parts).ok()
}

