struct Server {
    addr: SocketAddr,
    requests: Arc<Mutex<Vec<RecordedRequest>>>,
    stop: Arc<AtomicBool>,
    handle: Option<JoinHandle<()>>,
}

impl Server {
    /// Start a server that answers each incoming connection (one request per
    /// connection) using `handler`, indexed by hop (0-based).
    fn start(handler: impl Fn(usize, &RecordedRequest) -> Response + Send + Sync + 'static) -> Server {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let addr = listener.local_addr().unwrap();
        let requests = Arc::new(Mutex::new(Vec::new()));
        let stop = Arc::new(AtomicBool::new(false));
        let handle = {
            let requests = requests.clone();
            let stop = stop.clone();
            let handler = Arc::new(handler);
            thread::spawn(move || {
                let mut hop = 0;
                while !stop.load(Ordering::Relaxed) {
                    let (mut socket, _) = match listener.accept() {
                        Ok(v) => v,
                        Err(e) if e.kind() == io::ErrorKind::WouldBlock => {
                            thread::sleep(Duration::from_millis(5));
                            continue;
                        }
                        Err(e) => panic!("accept: {e}"),
                    };
                    socket.set_nonblocking(false).unwrap();
                    socket.set_read_timeout(Some(Duration::from_secs(5))).unwrap();
                    let req = read_request(&mut socket);
                    let response = handler(hop, &req);
                    requests.lock().unwrap().push(req);
                    write_response(&mut socket, &response);
                    hop += 1;
                }
            })
        };
        Server { addr, requests, stop, handle: Some(handle) }
    }

    fn url(&self, path: &str) -> String { format!("http://{}{}", self.addr, path) }

    fn recorded(&self) -> Vec<RecordedRequest> { self.requests.lock().unwrap().clone() }
}

impl Drop for Server {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Relaxed);
        if let Some(h) = self.handle.take() { h.join().unwrap(); }
    }
}
