        if buf.len() < pos + size + 2 { return None; }
        out.extend_from_slice(&buf[pos..pos + size]);
        pos += size;
        if &buf[pos..pos + 2] != b"\r\n" { panic!("malformed chunk"); }
        pos += 2;
        if size == 0 {
            return Some((out, pos));
        }
    }
}
