```rust
fn write_response(socket: &mut TcpStream, response: &Response) {
    let mut head = format!("HTTP/1.1 {} {}\r\n", response.status, response.reason);
    let mut has_cl = false;
    let mut has_conn = false;
    for (k, v) in &response.headers {
        head.push_str(&format!("{k}: {v}\r\n"));
        has_cl |= k.eq_ignore_ascii_case("content-length");
        has_conn |= k.eq_ignore_ascii_case("connection");
    }
    if !has_cl { head.push_str(&format!("Content-Length: {}\r\n", response.body.len())); }
    if !has_conn { head.push_str("Connection: close\r\n"); }
    head.push_str("\r\n");
    socket.write_all(head.as_bytes()).unwrap();
    socket.write_all(&response.body).unwrap();
    socket.flush().unwrap();
}
